import Foundation
import Darwin
import LauncherCore

@main struct ReadyStorageLibraryProbe {
  static func main()throws{
    let run=URL(fileURLWithPath:CommandLine.arguments[1]).resolvingSymlinksInPath(),fm=FileManager.default
