    func dir(_ name:String,_ mode:Int=0o755)throws->URL{let p=run.appendingPathComponent(name);try fm.createDirectory(at:p,withIntermediateDirectories:false,attributes:[.posixPermissions:mode]);return p}
    try check("freshRegistryHasNoImplicitUserLibraries",try repo.load().libraries.isEmpty)
