    try check("sameVolumeReservationsAreCountedAcrossLibraryRoots",rejects(.insufficientSpace){_=try repo.reserve(libraryID:second.id,store:.steam,gameID:"capacity-B",platform:.windows,bytes:free/2)})
    try check("bothLibraryStatusesShowTheSameSharedBudget",try repo.list().filter{$0.id==first.id || $0.id==second.id}.allSatisfy{$0.reservedBytes==large.remainingBytes})
    try repo.updateReservation(id:large.id,remainingBytes:free/4)
