    let macPath=try repo.installationURL(for:mac),windowsPath=try repo.installationURL(for:windows)
    let payload=macPath.appendingPathComponent("own-test-payload");try Data("keep downloaded bytes".utf8).write(to:payload)
    try check("nativeAndWindowsInstallationsAreSeparateAndProfileIndependent",macPath != windowsPath && macPath.path.hasPrefix(a.path+"/") && windowsPath.path.hasPrefix(a.path+"/"))
    try check("duplicateActiveInstallationCannotReserveTwice",rejects(.busy){_=try repo.reserve(libraryID:first.id,store:.steam,gameID:"480",platform:.macOS,bytes:1)})
    try check("activeReservationPreventsRemovingLibraryEntry",rejects(.busy){try repo.remove(id:first.id)})
    try repo.markInstalled(reservationID:mac.id);try repo.release(reservationID:windows.id)
    try check("completionAndCancellationPreserveGameFiles",fm.fileExists(atPath:payload.path) && (try repo.load().installations.first{$0.id==mac.installationID}?.state == .installed))
    let unknown=try repo.reserve(libraryID:first.id,store:.steam,gameID:"unknown-size",platform:.windows,bytes:nil)
    try check("unknownSizeIsPlanningNotZeroByteCapacityPromise",unknown.requiresPlanning && unknown.remainingBytes==nil && (try repo.list().first{$0.id==first.id}?.unplannedReservations==1))
    try check("unknownSizeCannotMaterializeInstallationBeforePlanning",rejects(.planningRequired){_=try repo.installationURL(for:unknown)})
    try repo.updateReservation(id:unknown.id,remainingBytes:4096);try repo.attachJob(reservationID:unknown.id,jobID:"fixture-job")
    try repo.reconcile(activeJobIDs:["fixture-job"])
    try check("jobBindingAndSizeSurviveRestartAndReconciliation",try StorageLibraryRepository(paths:paths).load().reservations.first{$0.id==unknown.id}?.jobID=="fixture-job" && repo.load().reservations.first{$0.id==unknown.id}?.remainingBytes==4096)
    try repo.reconcile(activeJobIDs:[])
    try check("missingRestoredJobReleasesOnlyMetadataReservation",try repo.load().reservations.isEmpty && fm.fileExists(atPath:payload.path))
    let unbound=try repo.reserve(libraryID:first.id,store:.gog,gameID:"unbound",platform:.windows,bytes:nil)
    try repo.reconcile(activeJobIDs:[]);try check("unattachedPlanningIsRetainedUntilExplicitStartupReconciliation",try repo.load().reservations.contains{$0.id==unbound.id})
    try repo.reconcile(activeJobIDs:[],releaseUnattached:true)
    let profileA=UUID(),profileB=UUID()
    let heldA=try repo.reserve(libraryID:first.id,store:.steam,gameID:"profile-A",platform:.windows,bytes:1,profileID:profileA)
    let heldB=try repo.reserve(libraryID:first.id,store:.steam,gameID:"profile-B",platform:.windows,bytes:1,profileID:profileB)
    try repo.attachJob(reservationID:heldA.id,jobID:"profile-A-job");try repo.attachJob(reservationID:heldB.id,jobID:"profile-B-job")
    try repo.reconcile(activeJobIDs:[],profileID:profileB)
    try check("restoringProfileBQueueCannotReleaseProfileAReservation",try repo.load().reservations.contains{$0.id==heldA.id && $0.ownerProfileID==profileA} && !repo.load().reservations.contains{$0.id==heldB.id})
    try repo.reconcile(activeJobIDs:["profile-A-job"],profileID:profileA)
    let retainedA=try repo.load().reservations.contains{$0.id==heldA.id}
    try repo.reconcile(activeJobIDs:[])
    try check("profileScopedRestoreKeepsLiveJobAndLegacyNilScopeCanReconcileAll",retainedA && (try repo.load().reservations.isEmpty))
    let preexisting=a.appendingPathComponent("Existing imported game");try fm.createDirectory(at:preexisting,withIntermediateDirectories:false)
    let imported=try repo.adopt(libraryID:first.id,store:.steam,gameID:"adopted",platform:.macOS,directory:preexisting)
    try check("adoptionRecordsExistingLocationWithoutMovingIt",imported.adopted && imported.state == .installed && fm.fileExists(atPath:preexisting.path))
    try check("adoptionCannotEscapeSelectedLibrary",rejects(.unsafePath){_=try repo.adopt(libraryID:first.id,store:.steam,gameID:"escape",platform:.macOS,directory:b)})
    let trap=try repo.reserve(libraryID:second.id,store:.epic,gameID:"trap",platform:.windows,bytes:1)
    let epic=b.appendingPathComponent(Store.epic.rawValue);try fm.createSymbolicLink(at:epic,withDestinationURL:a)
    try check("managedPathCreationNeverFollowsSymlinkOutsideLibrary",rejects(.unsafePath){_=try repo.installationURL(for:trap)} && !fm.fileExists(atPath:a.appendingPathComponent(SafePath.key("trap")).path))
    try repo.release(reservationID:trap.id);try fm.removeItem(at:epic)
    try repo.remove(id:first.id)
    try check("removeEntryDoesNotUninstallAndRetainsHistoricalInstallMetadata",try !repo.list().contains{$0.id==first.id} && repo.load().installations.contains{$0.id==mac.installationID} && fm.fileExists(atPath:payload.path))
    let restored=try repo.add(root:a,name:"Restored")
    try check("readdingLibraryKeepsStableIDAndInstallRecords",restored.id==first.id)
